<script>  import { CheckCircle2, AlertCircle, Info } from '@lucide/svelte';  import { ui } from '../lib/stores.svelte.js';</script><div class="toasts">  {#each ui.toasts as tst (tst.id)}    <div class="toast {tst.type}">      {#if tst.type === 'success'}<CheckCircle2 size={16} />      {:else if tst.type === 'error'}<AlertCircle size={16} />      {:else}<Info size={16} />{/if}      <span>{tst.message}</span>    </div>  {/each}</div><style>  .toasts {    position: fixed; bottom: 16px; right: 16px;    display: flex; flex-direction: column; gap: 8px;    z-index: 200; pointer-events: none;  }  .toast {    display: flex; align-items: center; gap: 8px;    background: var(--bg-2);    border: 1px solid var(--border);    border-radius: 6px;    padding: 10px 14px;    font-size: 12px;    color: var(--fg-0);    box-shadow: 0 4px 16px rgba(0,0,0,0.5);    animation: toastIn 0.2s ease-out;    max-width: 320px;  }  .toast.success { border-color: var(--success); color: var(--success); }  .toast.error   { border-color: var(--danger);  color: var(--danger); }  .toast.warn    { border-color: var(--accent);  color: var(--accent); }  .toast.info    { border-color: var(--border);  color: var(--fg-1); }  @keyframes toastIn {    from { opacity: 0; transform: translateX(20px); }    to   { opacity: 1; transform: translateX(0); }  }</style>